package com.ryanjei.orushio.pve.paper;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.UUID;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class SetupAdministratorOwnershipTest{@TempDir Path temp;
 @Test void 新規付与と明示引継ぎは再起動後も解除可能で解除も永続化する(){UUID id=UUID.randomUUID();var first=new SetupAdministratorOwnership(temp.resolve("data"));first.add(id);assertTrue(new SetupAdministratorOwnership(temp.resolve("data")).contains(id));first.remove(id);assertFalse(new SetupAdministratorOwnership(temp.resolve("data")).contains(id));}
 @Test void 旧grantログ1件とunrelatedOP1名でも自動migrationしない()throws Exception{UUID unrelated=UUID.randomUUID();Path data=temp.resolve("data"),logs=data.resolve("logs");Files.createDirectories(logs);Files.writeString(logs.resolve("audit-legacy.jsonl"),"{\"code\":\"SETUP_ADMINISTRATOR_GRANTED\"}\n");Files.writeString(temp.resolve("ops.json"),"[{\"uuid\":\""+unrelated+"\"}]");assertFalse(new SetupAdministratorOwnership(data).contains(unrelated));}
 @Test void 旧unsafe形式のownershipも証跡として採用しない()throws Exception{UUID id=UUID.randomUUID();Path data=temp.resolve("data");Files.createDirectories(data);Files.writeString(data.resolve("setup-administrators.yml"),"schemaVersion: \"1\"\nowned: \""+id+"\"\n");assertFalse(new SetupAdministratorOwnership(data).contains(id));assertTrue(Files.readString(data.resolve("setup-administrators.yml")).contains("ownershipEvidence"));}
 @Test void 監査なし既存OPや複数OP相当のUUIDを自動登録しない(){var ownership=new SetupAdministratorOwnership(temp.resolve("data"));assertFalse(ownership.contains(UUID.randomUUID()));assertFalse(ownership.contains(UUID.randomUUID()));}
}
